import{_ as p,a0 as s,w as o,s as m,ao as i,I as n,a1 as a,A as r,x as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"elementary OS 7 安装指南（附截图） | LCTT x X-CMD","titleTemplate":false,"description":"elementary OS 7 安装指南（附截图） | LCTT (202302) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"elementary OS 7 安装指南（附截图） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"elementary OS 7 安装指南（附截图） | LCTT (202302) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202302/20230206.0 ⭐️ Elementary OS 7 Installation Guide with Screenshots","title":"elementary OS 7 安装指南（附截图）","tag":"202302","desc":""},"relativePath":"202302/20230206.0 ⭐️ Elementary OS 7 Installation Guide with Screenshots.md","filePath":"[post].md"}'),u={name:"202302/20230206.0 ⭐️ Elementary OS 7 Installation Guide with Screenshots.md"};function d(b,t,y,w,h,g){const l=s("Link");return o(),m("div",null,[t[17]||(t[17]=i('<h1 id="elementary-os-7-安装指南-附截图" tabindex="-1">elementary OS 7 安装指南（附截图） <a class="header-anchor" href="#elementary-os-7-安装指南-附截图" aria-label="Permalink to “elementary OS 7 安装指南（附截图）”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202302/19/143743asfmbfrt7mc1tczb.jpg" alt=""></p><p>在这篇文章中，我们将介绍如何在笔记本电脑或台式机上一步一步地安装 elementary OS 7，并附有截图。它基于最新和稳定的 Ubuntu 22.04 LTS。</p><p>elementary OS 7 的代号为 “Horus”，并带来了很多改进，例如：</p><ul><li>改进了 AppCenter 和安装所有需要的应用。</li><li>改进了侧载和可选商店（Flathub）的体验。</li><li>最新的 GNOME Web 43，支持创建网络应用。</li><li>快速获得操作系统和应用的更新</li><li>电源配置文件管理</li><li>应用描述的改进</li></ul><h3 id="elementary-os-7-的系统要求" tabindex="-1">elementary OS 7 的系统要求 <a class="header-anchor" href="#elementary-os-7-的系统要求" aria-label="Permalink to “elementary OS 7 的系统要求”">​</a></h3><ul><li>双核 64 位处理器</li><li>4GB 内存或更多</li><li>32GB 硬盘</li><li>互联网接入</li><li>可启动的 USB 驱动器（4GB 存储空间）</li></ul><p>闲话少说，让我们进入安装步骤：</p><h3 id="_1-下载-elementary-os-7" tabindex="-1">1）下载 elementary OS 7 <a class="header-anchor" href="#_1-下载-elementary-os-7" aria-label="Permalink to “1）下载 elementary OS 7”">​</a></h3><p>使用下面的官方网址来下载 ISO 文件。</p>',10)),n("blockquote",null,[n("p",null,[n("strong",null,[a(l,{href:"https://elementary.io/"},{default:r(()=>[...t[0]||(t[0]=[e("下载 elementary OS 7 ISO",-1)])]),_:1})])])]),t[18]||(t[18]=n("p",null,"ISO 文件下载完成后，将其刻录到 USB 驱动器，并使其可启动。",-1)),t[19]||(t[19]=n("p",null,"在 Windows 操作系统中，用 Rufus 制作可启动的 USB 驱动器。在 Linux 中，请参考以下网址：",-1)),n("blockquote",null,[n("p",null,[n("strong",null,[a(l,{href:"https://www.linuxtechi.com/create-bootable-usb-disk-dvd-ubuntu-linux-mint/"},{default:r(()=>[...t[1]||(t[1]=[e("如何在 Ubuntu/Linux Mint 上创建可启动的 USB 驱动器",-1)])]),_:1})])])]),t[20]||(t[20]=i('<h3 id="_2-用可启动介质启动系统" tabindex="-1">2）用可启动介质启动系统 <a class="header-anchor" href="#_2-用可启动介质启动系统" aria-label="Permalink to “2）用可启动介质启动系统”">​</a></h3><p>现在用可启动的 USB 驱动器启动目标系统。从 BIOS 设置中把启动介质从硬盘改为 USB。当系统用 USB 驱动器启动时，我们将看到以下页面。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/02/BootScreen-elementaryOS7.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><h3 id="_3-选择安装语言" tabindex="-1">3）选择安装语言 <a class="header-anchor" href="#_3-选择安装语言" aria-label="Permalink to “3）选择安装语言”">​</a></h3><p>选择你喜欢的语言，然后点击“<ruby>选择<rt>Select</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/02/Keyboard-Layout-ElementaryOS7-Installation.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><h3 id="_4-选择键盘布局" tabindex="-1">4）选择键盘布局 <a class="header-anchor" href="#_4-选择键盘布局" aria-label="Permalink to “4）选择键盘布局”">​</a></h3><p>在这一步，你将被要求选择键盘布局，然后点击“<ruby>选择<rt>Select</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/02/Keyboard-Layout-ElementaryOS7-Installation.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><h3 id="_5-尝试或安装-elementary-os" tabindex="-1">5）尝试或安装 elementary OS <a class="header-anchor" href="#_5-尝试或安装-elementary-os" aria-label="Permalink to “5）尝试或安装 elementary OS”">​</a></h3><p>我们将看到下面的页面，在这里我们必须选择安装类型。它给了我们以下选项：</p><ul><li><ruby>试用演示模式<rt>Try Demo Mode</rt></ruby> – 试用 elementary OS 7 而不安装</li><li><ruby>擦除磁盘并安装<rt>Erase disk and Install</rt></ruby> – 安装程序将擦除整个磁盘并自动创建所需分区。</li><li><ruby>自定义安装（高级）<rt>Custom Install (Advanced)</rt></ruby> – 它将给我们一个选项来创建自定义分区。</li></ul><p>在这篇文章中，我将使用第二个选项（擦除磁盘并安装）。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/02/Installation-Type-ElementaryOS7.png?ezimgfmt=ngcb22/notWebP" alt=""></p><p>点击“<ruby>擦除磁盘并安装<rt>Erase disk and Install</rt></ruby>”。</p><p>在下面的屏幕上，选择要安装操作系统的驱动器，然后点击“<ruby>擦除并安装<rt>Erase and Install</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/02/Select-Drive-for-elementaryOS7-Installation.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>如果你想对设备的驱动器进行加密，那么点击“<ruby>选择密码<rt>Choose Password</rt></ruby>”，否则点击“<ruby>不加密<rt>Don’t Encrypt</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/02/Encryption-Drive-ElementaryOS7-Installation.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><h3 id="_6-安装进度" tabindex="-1">6）安装进度 <a class="header-anchor" href="#_6-安装进度" aria-label="Permalink to “6）安装进度”">​</a></h3><p>正如我们在下面看到的，安装已经开始，并且正在进行中。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/02/ElementaryOS7-Installation-Progress.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>安装完成后，安装程序将提示重启系统。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/02/Restart-Device-After-elementaryOS7-Installation.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>点击“<ruby>重启设备<rt>Restart Device</rt></ruby>”，不要忘记从 BIOS 设置中改变启动介质，以便用磁盘启动。</p><h3 id="_7-创建本地用户并设置主机名" tabindex="-1">7）创建本地用户并设置主机名 <a class="header-anchor" href="#_7-创建本地用户并设置主机名" aria-label="Permalink to “7）创建本地用户并设置主机名”">​</a></h3><p>当系统在安装后启动时，系统会提示你输入本地用户的详细信息和系统的主机名。</p><p>根据你的要求指定这些细节。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/02/Create-Local-Account-ElementaryOS7.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>点击“<ruby>完成设置<rt>Finish Setup</rt></ruby>”。</p><p>在下面的页面中，你将被提示输入你在上面创建的本地用户凭证。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/02/Login-screen-elementaryos7.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>输入凭证后，点击回车。</p><h3 id="_8-elementary-os-7-欢迎页" tabindex="-1">8）elementary OS 7 欢迎页 <a class="header-anchor" href="#_8-elementary-os-7-欢迎页" aria-label="Permalink to “8）elementary OS 7 欢迎页”">​</a></h3><p>我们将看到下面的欢迎页。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/02/ElementaryOS7-Welcome-Screen.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>选择“<ruby>跳过所有<rt>Skip All</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/02/Get-Started-ElementaryOS7.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>点击“<ruby>开始使用<rt>Get Started</rt></ruby>”，然后我们会看到下面的桌面。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/02/Desktop-Screen-ElementaryOS7-After-Installation.png" alt=""></p><p>很好，这表明你已经成功地在系统上安装了 elementary OS 7。这就是本指南的全部内容，请探索这个令人兴奋的 Linux 发行版并享受其中的乐趣吧😊。</p><hr>',42)),n("p",null,[t[3]||(t[3]=e("via: ",-1)),a(l,{href:"https://www.linuxtechi.com/elementary-os-7-installation-guide/"},{default:r(()=>[...t[2]||(t[2]=[e("https://www.linuxtechi.com/elementary-os-7-installation-guide/",-1)])]),_:1})]),n("p",null,[t[8]||(t[8]=e("作者：",-1)),a(l,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:r(()=>[...t[4]||(t[4]=[e("Pradeep Kumar",-1)])]),_:1}),t[9]||(t[9]=e(" 选题：",-1)),a(l,{href:"https://github.com/lkxed"},{default:r(()=>[...t[5]||(t[5]=[e("lkxed",-1)])]),_:1}),t[10]||(t[10]=e(" 译者：",-1)),a(l,{href:"https://github.com/geekpi"},{default:r(()=>[...t[6]||(t[6]=[e("geekpi",-1)])]),_:1}),t[11]||(t[11]=e(" 校对：",-1)),a(l,{href:"https://github.com/wxy"},{default:r(()=>[...t[7]||(t[7]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[14]||(t[14]=e("本文由 ",-1)),a(l,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[12]||(t[12]=[e("LCTT",-1)])]),_:1}),t[15]||(t[15]=e(" 原创编译，",-1)),a(l,{href:"https://linux.cn/"},{default:r(()=>[...t[13]||(t[13]=[e("Linux中国",-1)])]),_:1}),t[16]||(t[16]=e(" 荣誉推出",-1))])])}const x=p(u,[["render",d]]);export{f as __pageData,x as default};
